105	func (db *db) CreateCluster(ctx context.Context, c *appv1.Cluster) (*appv1.Cluster, error) {
106		if c.Server == appv1.KubernetesInternalAPIServerAddr {
107			settings, err := db.settingsMgr.GetSettings()
108			if err != nil {
109				return nil, err
110			}
111			if !settings.InClusterEnabled {
112				return nil, status.Errorf(codes.InvalidArgument, "cannot register cluster: in-cluster has been disabled")
113			}
114		}
115		secName, err := URIToSecretName("cluster", c.Server)
116		if err != nil {
117			return nil, err
118		}
119	
120		clusterSecret := &corev1.Secret{
121			ObjectMeta: metav1.ObjectMeta{
122				Name: secName,
123			},
124		}
125	
126		err = clusterToSecret(c, clusterSecret)
127		if err != nil {
128			return nil, err
129		}
130	
131		clusterSecret, err = db.createSecret(ctx, clusterSecret)
132		if err != nil {
133			if apierrors.IsAlreadyExists(err) {
134				return nil, status.Errorf(codes.AlreadyExists, "cluster %q already exists", c.Server)
135			}
136			return nil, err
137		}
138	
139		cluster, err := SecretToCluster(clusterSecret)
140		if err != nil {
141			return nil, status.Errorf(codes.InvalidArgument, "could not unmarshal cluster secret %s", clusterSecret.Name)
142		}
143		return cluster, db.settingsMgr.ResyncInformers()
144	}
