152	func (db *db) WatchClusters(ctx context.Context,
153		handleAddEvent func(cluster *appv1.Cluster),
154		handleModEvent func(oldCluster *appv1.Cluster, newCluster *appv1.Cluster),
155		handleDeleteEvent func(clusterServer string),
156	) error {
157		argoSettings, err := db.settingsMgr.GetSettings()
158		if err != nil {
159			return err
160		}
161	
162		localCls := db.getLocalCluster()
163		if argoSettings.InClusterEnabled {
164			localCls, err = db.GetCluster(ctx, appv1.KubernetesInternalAPIServerAddr)
165			if err != nil {
166				return fmt.Errorf("could not get local cluster: %w", err)
167			}
168			handleAddEvent(localCls)
169		}
170	
171		db.watchSecrets(
172			ctx,
173			common.LabelValueSecretTypeCluster,
174	
175			func(secret *corev1.Secret) {
176				cluster, err := SecretToCluster(secret)
177				if err != nil {
178					log.Errorf("could not unmarshal cluster secret %s", secret.Name)
179					return
180				}
181				if cluster.Server == appv1.KubernetesInternalAPIServerAddr {
182					if argoSettings.InClusterEnabled {
183						// change local cluster event to modified, since it cannot be added at runtime
184						handleModEvent(localCls, cluster)
185						localCls = cluster
186					}
187					return
188				}
189				handleAddEvent(cluster)
190			},
191	
192			func(oldSecret *corev1.Secret, newSecret *corev1.Secret) {
193				oldCluster, err := SecretToCluster(oldSecret)
194				if err != nil {
195					log.Errorf("could not unmarshal cluster secret %s", oldSecret.Name)
196					return
197				}
198				newCluster, err := SecretToCluster(newSecret)
199				if err != nil {
200					log.Errorf("could not unmarshal cluster secret %s", newSecret.Name)
201					return
202				}
203				if newCluster.Server == appv1.KubernetesInternalAPIServerAddr {
204					localCls = newCluster
205				}
206				handleModEvent(oldCluster, newCluster)
207			},
208	
209			func(secret *corev1.Secret) {
210				if string(secret.Data["server"]) == appv1.KubernetesInternalAPIServerAddr && argoSettings.InClusterEnabled {
211					// change local cluster event to modified, since it cannot be deleted at runtime, unless disabled.
212					newLocalCls := db.getLocalCluster()
213					handleModEvent(localCls, newLocalCls)
214					localCls = newLocalCls
215				} else {
216					handleDeleteEvent(string(secret.Data["server"]))
217				}
218			},
219		)
220	
221		return err
222	}
